#include <stdio.h>

int main(void)
{
    double x, total = 0, lo = 0, hi = 0;
    int count = 0, alarms = 0;
    while (scanf("%lf", &x) == 1) {
        if (count == 0 || x < lo) lo = x;
        if (count == 0 || x > hi) hi = x;
        if (x > 30.0) alarms++;
        total += x;
        count++;
    }
    if (count == 0) {
        printf("no readings\n");
        return 0;
    }
    printf("count %d\n", count);
    printf("min %.1f\n", lo);
    printf("max %.1f\n", hi);
    printf("average %.1f\n", total / count);
    printf("alarms %d\n", alarms);
    return 0;
}
